import { PieChartAdapter, usePieChart } from '@dreadnought/react/unstyled';
const data=[{id:'a',label:'A',value:60},{id:'b',label:'B',value:40}];
function Summary(){const {visible}=usePieChart();return <p>Видимых: {visible.length}</p>;}
export function Example(){return <PieChartAdapter label="Данные" data={data} innerRadius={0.6}><Summary/><PieChartAdapter.Legend>{({defaultContent})=><span>{defaultContent}</span>}</PieChartAdapter.Legend><PieChartAdapter.Plot tooltipContent={({defaultContent})=><div>{defaultContent}</div>}>{({defaultContent})=>defaultContent}</PieChartAdapter.Plot><PieChartAdapter.Table/></PieChartAdapter>;}
